      stem: "어느 지역에서 한 해 영아사망자가 20명, 신생아사망자가 16명이었다. 이 지역의 알파 인덱스(α-index)는?",
      choices: ["1.25","0.80","1.00","1.60","2.00"],
      answerIndex: 0,
      explainCorrect: "알파 인덱스는 영아사망 수를 신생아사망 수로 나눈 값으로 20/16=1.25이다. 이 값이 1에 가까울수록 신생아기 이후의 예방 가능한 사망이 적다는 뜻이므로 보건수준이 높다고 평가한다.",
      explainWrong: ["","0.80은 분자와 분모를 뒤집어 계산한 값이다. 영아사망에는 신생아사망이 포함되므로 알파 인덱스는 1보다 작을 수 없다.","1.00은 영아사망이 전부 신생아기 사망일 때의 이론적 최솟값으로, 이 지역의 계산값이 아니다.","1.60은 두 수치의 차이(4명)를 잘못 활용한 값으로 계산 근거가 없다.","2.00은 근거 없는 값이며, 20/16을 올바르게 계산하면 1.25가 된다."],
