      explainWrong: ["","오타와 헌장은 1986년 제1차 건강증진 국제회의에서 채택된 건강증진에 관한 헌장이다.","리우 선언은 1992년 환경과 개발에 관한 유엔 회의의 선언으로 보건의료 전략 선언이 아니다.","헬싱키 선언은 사람을 대상으로 하는 의학 연구의 윤리 원칙을 다룬 선언이다.","방콕 헌장은 2005년 세계화 시대의 건강증진 전략을 다룬 헌장으로 일차보건의료 선언이 아니다."],
