      explainWrong: ["","칼시토닌은 갑상샘에서 분비되어 뼈에 칼슘을 침착시켜 혈중 칼슘을 낮추는 반대 작용을 한다.","티록신은 기초대사율을 조절하는 갑상샘호르몬으로 칼슘 조절이 주작용이 아니다.","알도스테론은 나트륨과 칼륨의 균형을 조절하는 부신겉질호르몬이다.","성장호르몬은 뼈와 조직의 성장을 촉진할 뿐 저칼슘혈증에 대한 즉각적 조절 호르몬이 아니다."],
