      explainWrong: ["","레닌은 혈압 저하 시 콩팥에서 분비되어 레닌-안지오텐신 계통을 작동시키는 효소이다.","트롬보포이에틴은 주로 간에서 만들어져 혈소판 생성을 촉진한다.","알도스테론은 부신겉질에서 분비되어 나트륨·칼륨 균형을 조절한다.","칼시트리올은 콩팥에서 활성화되지만 칼슘 흡수를 촉진하는 호르몬으로, 적혈구 생성과 직접 관련이 없다."],
