      explainWrong: ["","나트륨은 세포 외액의 주 양이온이라 용혈 시 오히려 희석되어 약간 감소할 수 있고, 염소와 총단백도 유의한 위증가를 보이지 않는다.","포도당은 용혈보다 방치 시 해당작용으로 감소하는 것이 문제이며, 요산과 BUN은 용혈로 크게 오르는 항목이 아니다.","칼슘과 마그네슘은 용혈로 크게 상승하는 대표 항목이 아니며, 일부는 헤모글로빈 간섭에 의한 측정 오차 수준이다.","알부민과 지질 항목은 적혈구 내 농도가 낮아 용혈로 위증가하지 않는다."],
