      choices: ["해당작용 효소(enolase)를 억제하여 포도당 소모를 막는다","칼슘을 킬레이트하여 응고를 완전히 차단한다","트롬빈을 활성화하여 혈청 분리를 촉진한다","적혈구막을 안정화하여 용혈을 방지한다","포도당 산화효소를 활성화하여 측정 감도를 높인다"],
