      explainWrong: ["","칼슘 킬레이트에 의한 항응고는 EDTA나 구연산염의 작용이며, NaF 단독의 항응고 능력은 약해 별도의 항응고제를 병용한다.","트롬빈 활성화는 응고촉진제가 든 혈청관의 역할로 NaF와는 반대 개념이다.","NaF는 용혈 방지제가 아니며 적혈구막 안정화 작용도 없다.","NaF는 측정 시약의 효소를 활성화하는 것이 아니라 검체 내 해당 효소를 억제하는 보존제이다."],
