      explainWrong: ["","변화 방향이 반대이다. 칼륨염이 더해지므로 칼륨은 오르고, 칼슘은 킬레이트되어 떨어진다.","EDTA 혼입이 나트륨과 염소에 주는 영향은 칼륨·칼슘 변화에 비해 특징적이지 않다.","포도당과 요산은 EDTA 혼입으로 특징적으로 변하는 항목이 아니다.","총단백과 알부민은 EDTA 혼입의 대표적인 간섭 항목이 아니다."],
