      choices: ["혈액배양 → 구연산염(청색) → 혈청관 → 헤파린(녹색) → EDTA(보라) → NaF(회색)","EDTA(보라) → NaF(회색) → 혈청관 → 구연산염(청색) → 혈액배양 → 헤파린(녹색)","NaF(회색) → EDTA(보라) → 헤파린(녹색) → 혈청관 → 구연산염(청색) → 혈액배양","구연산염(청색) → 혈액배양 → EDTA(보라) → 헤파린(녹색) → NaF(회색) → 혈청관","혈청관 → EDTA(보라) → 구연산염(청색) → NaF(회색) → 헤파린(녹색) → 혈액배양"],
